package com.akshay.stockflow.product;
import com.akshay.stockflow.audit.StockMovement;
import com.akshay.stockflow.audit.StockMovementRepository;
import jakarta.transaction.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {
private final ProductRepository products; private final StockMovementRepository movements; public ProductController(ProductRepository products,StockMovementRepository movements){this.products=products;this.movements=movements;}
@GetMapping public List<Product> all(@RequestParam(required=false) String q,@RequestParam(required=false) Boolean lowStock){List<Product> rows=(q==null||q.isBlank())?products.findAll():products.findByNameContainingIgnoreCaseOrSkuContainingIgnoreCase(q,q);return Boolean.TRUE.equals(lowStock)?rows.stream().filter(p->p.getQuantity()<=p.getReorderLevel()).toList():rows;}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public Product create(@Valid @RequestBody ProductInput i){if(products.existsBySkuAndWarehouse(i.sku(),i.warehouse()))throw new ResponseStatusException(HttpStatus.CONFLICT,"SKU already exists in this warehouse");return products.save(new Product(i.name(),i.sku(),i.category(),i.warehouse(),i.quantity(),i.reorderLevel(),i.unitPrice()));}
@PatchMapping("/{id}/stock") @Transactional public Product adjust(@PathVariable Long id,@Valid @RequestBody StockAdjustment a){Product p=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(a.change()==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Stock adjustment must be non-zero");int before=p.getQuantity();int next=before+a.change();if(next<0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Stock cannot become negative");p.setQuantity(next);Product saved=products.save(p);movements.save(new StockMovement(p.getId(),p.getSku(),p.getWarehouse(),a.change()>=0?"RECEIPT":"ISSUE",before,a.change(),next,a.reason()));return saved;}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){products.delete(products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found")));}
@GetMapping("/summary") public Map<String,Object> summary(){List<Product> all=products.findAll();return Map.of("skuCount",all.size(),"unitsOnHand",all.stream().mapToInt(Product::getQuantity).sum(),"lowStockCount",all.stream().filter(p->p.getQuantity()<=p.getReorderLevel()).count(),"inventoryValue",all.stream().mapToDouble(p->p.getQuantity()*p.getUnitPrice()).sum());}
public record ProductInput(@NotBlank String name,@NotBlank String sku,@NotBlank String category,@NotBlank String warehouse,@Min(0) int quantity,@Min(0) int reorderLevel,@DecimalMin("0.0") double unitPrice){} public record StockAdjustment(@NotNull @Min(-1000000) @Max(1000000) Integer change,String reason){}
}
